-- Supabase / PostgreSQL Database Dump
-- 50,000 Indian Snacks & Packaged Foods (Per 50g macros)

CREATE TABLE IF NOT EXISTS snacks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    barcode VARCHAR(20) UNIQUE NOT NULL,
    brand VARCHAR(100) NOT NULL,
    product_name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL,
    serving_size_g NUMERIC(5,2) DEFAULT 50.00,
    calories_kcal NUMERIC(6,2) NOT NULL,
    protein_g NUMERIC(5,2) NOT NULL,
    carbohydrates_g NUMERIC(5,2) NOT NULL,
    fat_g NUMERIC(5,2) NOT NULL,
    fiber_g NUMERIC(5,2) DEFAULT 0.00,
    sodium_mg NUMERIC(6,2) DEFAULT 0.00,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_snacks_barcode ON snacks(barcode);

